mapper.select:
select item_type as itemType, status as status, count(*) as cnt from sgj_item where del_flag = '0'
and create_by = #{createBy}
group by item_type, status

select count(*) from sgj_note where del_flag = '0'
and create_by = #{createBy}
and is_public = '1'

select item_id as itemId, item_type as itemType, title, status, rating, tags, cover_url as coverUrl, create_by as createBy, create_time as createTime, update_by as updateBy, update_time as updateTime, remark from sgj_item where del_flag = '0' and status = 'WANT'
and create_by = #{createBy}
order by create_time desc, item_id desc limit #{limit}

select item_id as itemId, item_type as itemType, title, status, rating, comment, tags, cover_url as coverUrl, finish_date as finishDate, create_by as createBy, create_time as createTime, update_by as updateBy, update_time as updateTime, remark from sgj_item where del_flag = '0' and status = 'DONE'
and create_by = #{createBy}
order by finish_date desc, update_time desc, item_id desc limit #{limit} offset #{offset}

select note_id as noteId, item_id as itemId, title, content, tags, is_public as isPublic, create_by as createBy, create_time as createTime, update_by as updateBy, update_time as updateTime, remark from sgj_note where del_flag = '0'
and create_by = #{createBy}
and is_public = '1'
order by create_time desc, note_id desc limit #{limit}
